import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import base64
from io import BytesIO
from datetime import datetime
import re
from collections import Counter

def get_base64_image(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    buf.seek(0)
    return base64.b64encode(buf.getvalue()).decode('utf-8')

# Read Data
df = pd.read_csv('/app/benchmark/data.csv')

# --- KPIs ---
total_questions = len(df)
years = sorted(df['year'].unique())
total_years = len(years)

type_counts = df['type'].value_counts()
type_ratios = (type_counts / total_questions * 100).round(1)

yearly_counts = df.groupby('year').size()
yearly_type_counts = df.groupby(['year', 'type']).size().unstack(fill_value=0)

# Calculate Year-over-Year Change
yoy_change = yearly_counts.diff()
yoy_pct_change = (yearly_counts.pct_change() * 100).round(1)

avg_per_type = df.groupby('type').size() / total_years

# --- Charts ---
plt.style.use('seaborn-v0_8-whitegrid')

# 1. Yearly Distribution (Bar Chart)
fig1, ax1 = plt.subplots(figsize=(10, 5))
yearly_counts.plot(kind='bar', ax=ax1, color='#3498db')
ax1.set_title('Total Questions per Year', fontsize=14)
ax1.set_xlabel('Year')
ax1.set_ylabel('Count')
ax1.set_xticklabels(ax1.get_xticklabels(), rotation=45)
fig1.tight_layout()
chart_yearly_dist = get_base64_image(fig1)
plt.close(fig1)

# 2. Question Type Ratio Over Time (Stacked Bar Chart)
fig2, ax2 = plt.subplots(figsize=(10, 5))
yearly_type_counts.plot(kind='bar', stacked=True, ax=ax2, colormap='viridis')
ax2.set_title('Question Type Composition per Year', fontsize=14)
ax2.set_xlabel('Year')
ax2.set_ylabel('Count')
ax2.legend(title='Question Type')
ax2.set_xticklabels(ax2.get_xticklabels(), rotation=45)
fig2.tight_layout()
chart_type_ratio = get_base64_image(fig2)
plt.close(fig2)

# 3. Overall Question Type Distribution (Pie Chart)
fig3, ax3 = plt.subplots(figsize=(7, 7))
ax3.pie(type_counts, labels=type_counts.index, autopct='%1.1f%%', startangle=90, colors=['#2ecc71', '#3498db', '#e74c3c'])
ax3.set_title('Overall Question Type Distribution', fontsize=14)
fig3.tight_layout()
chart_type_pie = get_base64_image(fig3)
plt.close(fig3)

# --- Topic Analysis ---
stop_words = set(['the', 'is', 'a', 'in', 'of', 'to', 'and', 'what', 'which', 'for', 'are', 'an', 'by', 'as', 'on', 'with', 'from', 'this', 'or', 'be', 'how', 'do', 'does', 'can', 'it', 'write', 'define', 'explain', 'describe', 'differentiate', 'between', 'give', 'any', 'two', 'purpose', 'statement', 'following', 'called', 'used', 'use', 'using', 'types', 'different', 'program', 'function', 'functions', 'example', 'examples', 'name', 'briefly', 'also', 'all', 'not', 'one', 'have', 'has', 'their', 'there'])

def clean_text(text, qtype):
    # Remove everything after $ for MCQs (and Long if sub-parts are not relevant, but let's just use first part for topic analysis)
    first_part = str(text).split('$')[0].lower()
    # Remove punctuation
    first_part = re.sub(r'[^\w\s]', '', first_part)
    words = first_part.split()
    return [w for w in words if w not in stop_words and len(w) > 2]

all_words = []
for idx, row in df.iterrows():
    all_words.extend(clean_text(row['question'], row['type']))

word_freq = Counter(all_words).most_common(20)

fig4, ax4 = plt.subplots(figsize=(10, 6))
words, counts = zip(*word_freq)
sns.barplot(x=list(counts), y=list(words), ax=ax4, palette='rocket')
ax4.set_title('Top 20 Recurring Keywords in Questions (2015-2025)', fontsize=14)
ax4.set_xlabel('Frequency')
ax4.set_ylabel('Keyword')
fig4.tight_layout()
chart_keywords = get_base64_image(fig4)
plt.close(fig4)


# --- HTML Generation ---

html_content = f"""
